   202	    public static class LongestStageProcessFunction extends KeyedProcessFunction<Long, StageInput, Tuple2<Long, Integer>> {
   203	
   204	        private final long inactivityGapMicros;
   205	
   206	        private transient ValueState<Long> lastSubmitTimestamp;
   207	        private transient ValueState<Integer> currentStageCount;
   208	        private transient ValueState<Integer> longestStageCount;
   209	        private transient ValueState<Boolean> finished;
   210	
   211	        public LongestStageProcessFunction(long inactivityGapMicros) {
   212	            this.inactivityGapMicros = inactivityGapMicros;
   213	        }
   214	
   215	        @Override
   216	        public void open(Configuration parameters) {
   217	            lastSubmitTimestamp = getRuntimeContext().getState(new ValueStateDescriptor<>("lastSubmitTs", Long.class));
   218	            currentStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("currentStageCount", Integer.class));
   219	            longestStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("longestStageCount", Integer.class));
   220	            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
   221	        }
   222	
   223	        @Override
   224	        public void processElement(StageInput value, Context ctx, Collector<Tuple2<Long, Integer>> out) throws Exception {
   225	            Boolean done = finished.value();
   226	            if (done != null && done) {
   227	                return;
   228	            }
   229	
   230	            if (value.isFinish) {
   231	                finalizeStage();
   232	                finished.update(true);
   233	                Integer longest = longestStageCount.value();
   234	                out.collect(Tuple2.of(value.jobId, longest == null ? 0 : longest));
   235	                return;
   236	            }
   237	
   238	            Long lastTs = lastSubmitTimestamp.value();
   239	            Integer current = currentStageCount.value();
   240	            if (current == null) {
   241	                current = 0;
   242	            }
   243	
   244	            if (lastTs != null && value.timestampMicros - lastTs > inactivityGapMicros) {
   245	                updateLongest(current);
   246	                current = 0;
   247	            }
   248	
   249	            currentStageCount.update(current + 1);
   250	            lastSubmitTimestamp.update(value.timestampMicros);
   251	        }
   252	
   253	        private void finalizeStage() throws Exception {
   254	            Integer current = currentStageCount.value();
   255	            if (current == null) {
   256	                current = 0;
   257	            }
   258	            updateLongest(current);
   259	        }
   260	
   261	        private void updateLongest(int currentCount) throws Exception {
   262	            Integer longest = longestStageCount.value();
   263	            if (longest == null || currentCount > longest) {
   264	                longestStageCount.update(currentCount);
   265	            }
   266	        }
